// ErrCanceled is returned by Choose when the user declines to pick (blank input
// or "q"). It's a deliberate user action, not an I/O failure — distinguish it
// from a real error with errors.Is(err, input.ErrCanceled).
var ErrCanceled = errors.New("input: selection canceled")

// sharedStdin is the package-level reader over os.Stdin, initialized lazily on
// first use. Every stdin-reading entry point reads through it so buffered
// bytes survive between calls: bufio pulls ahead of the first line it returns,
// and a fresh per-call reader would throw that look-ahead away — the next
// prompt would silently lose piped/pasted input. Interactive TTYs mask the
// bug (one Read per typed line), which is why it only shows on pipes and
// redirected input. If os.Stdin has been swapped since the reader was created
// (tests, daemons re-plumbing the stream), the reader is rebuilt on the new
// stream — buffered bytes from the old stream were the old stream's business.
var sharedStdin *bufio.Reader

var sharedStdinFile *os.File

// readStdinLine reads one line from the shared stdin reader, trimming
// surrounding whitespace. All prompt-style entry points (ReadLine, the
// non-TTY password fallback, Confirm, Choose) go through here.
func readStdinLine() (string, error) {
	if sharedStdin == nil || sharedStdinFile != os.Stdin {
		sharedStdin = bufio.NewReader(os.Stdin)
		sharedStdinFile = os.Stdin
	}
	text, err := sharedStdin.ReadString('\n')
	if err != nil {
		return kukistring.TrimSpace(text), err
	}
	return kukistring.TrimSpace(text), nil
}

// ReadPasswordAllowEcho reads a password with an explicit non-TTY fallback.
// Use only when the non-interactive behavior is deliberate (tests, scripts).
func ReadPasswordAllowEcho(prompt string) (string, error) {
	if prompt != "" {
		fmt.Print(prompt)
	}
	if !termpkg.IsTTY(os.Stdin) {
		return readStdinLine()
	}
	fd := int(os.Stdin.Fd())
	bytes, err_1 := term.ReadPassword(fd)
	if err_1 != nil {
		return "", err_1
	}
	fmt.Println()
	return string(bytes), nil
}

// ReadLine reads a line from standard input.
// It optionally prints a prompt if provided.
// Trims leading and trailing whitespace from the result.
// Reads through the shared stdin reader, so buffered input survives between
// sequential calls (a fresh reader per call would drop bufio look-ahead and
// lose piped/pasted lines after the first prompt).
// On EOF (e.g. piped input that ends mid-read) returns the partial line
// along with io.EOF — callers using `onerr return ""` will silently get
// an empty string and should check for EOF explicitly if that matters.
func ReadLine(prompt string) (string, error) {
	if prompt != "" {
		fmt.Print(prompt)
	}
	return readStdinLine()
}

// ReadPassword reads a line from stdin without echoing it. Fails closed (returns
// an error) when stdin is not a TTY so silent echo fallback is never
// accidental. Callers that explicitly want an echoed fallback (e.g. tests,
// scripts) must use ReadPasswordAllowEcho.
func ReadPassword(prompt string) (string, error) {
	if prompt != "" {
		fmt.Print(prompt)
	}
	if !termpkg.IsTTY(os.Stdin) {
		return "", errors.New("input: stdin is not a TTY; password input requires a terminal (use ReadPasswordAllowEcho for non-interactive use)")
	}
	fd := int(os.Stdin.Fd())
	bytes, err_2 := term.ReadPassword(fd)
	if err_2 != nil {
		return "", err_2
	}
	fmt.Println()
	return string(bytes), nil
}

// Confirm asks a yes/no question and returns true for y/yes, false otherwise
// Returns an error only if reading stdin fails
// Example: ok := input.Confirm("Proceed?") onerr return
func Confirm(prompt string) (bool, error) {
	answer, err_3 := ReadLine(fmt.Sprintf("%v [y/N]: ", prompt))
	if err_3 != nil {
		err_3 = fmt.Errorf("confirm prompt: %w", err_3)
		return false, err_3
	}
	lower := kukistring.ToLower(kukistring.TrimSpace(answer))
	return lower == "y" || lower == "yes", nil
}

// Choose presents a numbered list of options and returns the 0-based index of the selection.
// Returns an error if the user cancels (q/Q/empty) or enters an invalid number.
// When the caller wants the chosen option rather than its position, use ChooseValue.
// Example:
//
//	repos := list of string{"myorg/api", "myorg/web"}
//	i := input.Choose("Select repo:", repos) onerr return
//	print("You chose: {repos[i]}")
func Choose(prompt string, options []string) (int, error) {
	return chooseIndex(prompt, options)
}

// chooseIndex is the shared numbered-list prompt: render, read, validate.
func chooseIndex(prompt string, display []string) (int, error) {
	if len(display) == 0 {
		return -1, errors.New("no options provided")
	}
	fmt.Println(prompt)
	fmt.Println("")
	for i, opt := range display {
		fmt.Printf("  %v) %v\n", i+1, opt)
	}
	fmt.Println("")
	raw, err_4 := ReadLine("Enter number (or q to quit): ")
	if err_4 != nil {
		err_4 = fmt.Errorf("choose prompt: %w", err_4)
		return 0, err_4
	}
	trimmed := kukistring.TrimSpace(raw)
	if trimmed == "" || trimmed == "q" || trimmed == "Q" {
		return -1, ErrCanceled
	}
	val, err_5 := parse.Int(trimmed)
	if err_5 != nil {
		return -1, fmt.Errorf("invalid selection: %v", trimmed)
	}
	if val < 1 || val > len(display) {
		return -1, fmt.Errorf("selection out of range: %v", val)
	}
	return val - 1, nil
}

// ChooseValue presents a numbered list and returns the selected option
// itself — the index Choose reports is an implementation detail for callers
// who want the thing, not its position. Options are listed using their
// printed form, so give printable values (string, enum with String(), etc.).
// Cancels (ErrCanceled) on q/empty exactly like Choose.
// Example:
//
//	env := input.ChooseValue("Select environment:", list of string{"dev", "prod"}) onerr return
func ChooseValue[T any](prompt string, options []T) (T, error) {
	display := []string{}
	for _, opt := range options {
		display = append(display, fmt.Sprintf("%v", opt))
	}
	i, err := chooseIndex(prompt, display)
	if err != nil {
		var _zero0 T
		return _zero0, err
	}
	return options[i], nil
}

// FieldKind tags which prompt style a FormField uses. Set by the builder
// methods (Text/Confirm/Choose); callers don't construct it directly.
type FieldKind int

const (
	FieldKindText    FieldKind = 0
	FieldKindConfirm FieldKind = 1
	FieldKindChoose  FieldKind = 2
)

func AllFieldKind() []FieldKind {
	return []FieldKind{FieldKindText, FieldKindConfirm, FieldKindChoose}
}

func (e FieldKind) String() string {
	switch e {
	case FieldKindText:
		return "Text"
	case FieldKindConfirm:
		return "Confirm"
	case FieldKindChoose:
		return "Choose"
	default:
		return fmt.Sprintf("FieldKind(%d)", int(e))
	}
}

