// Validate attaches a validator to a previously-added field. The validator
// returns nil to accept, or an error whose message is shown to the user
// before re-prompting. No-op if key isn't found.
func (f *Form) Validate(key string, validator func(string) error) *Form {
	i := 0
	for i < len(f.Fields) {
		if f.Fields[i].Key == key {
			f.Fields[i].Validator = validator
			return f
		}
		i += 1
	}
	return f
}

// Default sets the value substituted for a previously-added field when the
