// Run prompts each field in order, retrying on validator failure.
// Returns an error if stdin reading fails or a Choose field is cancelled.
func (f *Form) Run() error {
	reader := bufio.NewReader(f.R)
	for _, field := range f.Fields {
		for {
			value, err := promptField(f.W, reader, field)
			if err != nil {
				return err
			}
			if field.Validator != nil {
				vErr := field.Validator(value)
				if vErr != nil {
					fmt.Fprintf(f.W, "  %v\n", vErr)
					continue
				}
			}
			f.Values[field.Key] = value
			break
		}
	}
	return nil
}

// String returns the collected value for key, or "" if unset.
func (f *Form) String(key string) string {
	return f.Values[key]
}

// Bool returns true if the collected value for key equals "true". Use after
// Confirm fields. Returns false for unset or non-confirm keys.
func (f *Form) Bool(key string) bool {
	return f.Values[key] == "true"
}

// promptField runs one field and returns its raw collected value as a string.
// - Text:    trimmed line
// - Confirm: "true" if y/yes, else "false"
// - Choose:  the selected option string
func promptField(w *os.File, reader *bufio.Reader, field FormField) (string, error) {
	switch field.Kind {
	case FieldKindText:
		line, err_6 := readLineFrom(w, reader, field.Prompt)
		if err_6 != nil {
			return "", err_6
		}
		if line == "" && field.Default != "" {
			return field.Default, nil
		}
		return line, nil
	case FieldKindConfirm:
		line, err_7 := readLineFrom(w, reader, fmt.Sprintf("%v[y/N]: ", field.Prompt))
		if err_7 != nil {
			return "", err_7
		}
		lower := kukistring.ToLower(kukistring.TrimSpace(line))
		if lower == "y" || lower == "yes" {
			return "true", nil
		}
		return "false", nil
	case FieldKindChoose:
		return promptChoose(w, reader, field)
	}
	return "", fmt.Errorf("unknown field kind: %v", field.Kind)
}

// promptChoose renders a numbered list and returns the selected option string.
func promptChoose(w *os.File, reader *bufio.Reader, field FormField) (string, error) {
	if len(field.Options) == 0 {
		return "", fmt.Errorf("no options for %v", field.Key)
	}
	fmt.Fprintln(w, field.Prompt)
	for i, opt := range field.Options {
		fmt.Fprintf(w, "  %v) %v\n", i+1, opt)
	}
	raw, err_8 := readLineFrom(w, reader, "Enter number (or q to quit): ")
	if err_8 != nil {
		return "", err_8
	}
	trimmed := kukistring.TrimSpace(raw)
	if trimmed == "" || trimmed == "q" || trimmed == "Q" {
		return "", errors.New("cancelled")
	}
	val, err_9 := parse.Int(trimmed)
	if err_9 != nil {
		return "", fmt.Errorf("invalid selection: %v", trimmed)
	}
	if val < 1 || val > len(field.Options) {
		return "", fmt.Errorf("selection out of range: %v", val)
	}
	return field.Options[val-1], nil
}

// readLineFrom reads one line from reader, optionally printing prompt to w.
// Used by Form so prompts and input share a configurable IO pair (testable).
func readLineFrom(w *os.File, reader *bufio.Reader, prompt string) (string, error) {
	if prompt != "" {
		fmt.Fprint(w, prompt)
	}
	text, err_10 := reader.ReadString('\n')
	if err_10 != nil {
		return "", err_10
	}
	return kukistring.TrimSpace(text), nil
}
